observation.query:
SELECT DISTINCT ?graph ?subject ?predicate ?object
WHERE {
  VALUES ?graph {
    <urn:graphragprov:unit:u_1e93daacd7116a52>
    <urn:graphragprov:unit:u_47bb8176c062ce03>
    <urn:graphragprov:unit:u_4f93a80e10fb4313>
  }
  GRAPH ?graph {
    ?subject ?predicate ?object .
    FILTER(isIRI(?subject))
  }
}
ORDER BY ?graph ?subject ?predicate ?object
